fn main() -> Text:
  let values = for x in list_slice(list_reverse([31, 7, -2, 90]), 1, 2):
    int_text(x)
  join_text(values, ":")

fn failure_text() -> Result<Int, DataError>:
  Err("safe detail")

fn main() -> Text:
  match failure_text():
    Ok(number) => int_text(number)
    Err(error) => error_message(error)

fn describe_data_result(value: Result<Int, DataError>) -> Text:
  match value:
    Ok(number) => int_text(number)
    Err(error) => error_message(error)

fn main() -> Text:
  describe_data_result(Err("argument detail"))

fn failure_for_try() -> Result<Int, DataError>:
  Err("propagated detail")

fn relay_data_result() -> Result<Int, DataError>:
  let number = failure_for_try()?
  Ok(number + 1)

fn main() -> Text:
  match relay_data_result():
    Ok(number) => int_text(number)
    Err(error) => error_message(error)
